// Differential checks of FunctionCompose01-pbo.js against Lean, generated by leanscript --check
import * as M from "./FunctionCompose01-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("f(\"\")", () => M.f(""), "a", false);
check("f(\"a\")", () => M.f("a"), "a", false);
check("f(\"hello world\")", () => M.f("hello world"), "a", false);
check("f(\"héllo, wörld\")", () => M.f("héllo, wörld"), "a", false);
check("f(\"abcabc\")", () => M.f("abcabc"), "a", false);
check("g(\"\")", () => M.g(""), "b", false);
check("g(\"a\")", () => M.g("a"), "b", false);
check("g(\"hello world\")", () => M.g("hello world"), "b", false);
check("g(\"héllo, wörld\")", () => M.g("héllo, wörld"), "b", false);
check("g(\"abcabc\")", () => M.g("abcabc"), "b", false);
check("test1(\"\")", () => M.test1(""), "a", false);
check("test1(\"a\")", () => M.test1("a"), "a", false);
check("test1(\"hello world\")", () => M.test1("hello world"), "a", false);
check("test1(\"héllo, wörld\")", () => M.test1("héllo, wörld"), "a", false);
check("test1(\"abcabc\")", () => M.test1("abcabc"), "a", false);
check("test2(\"\")", () => M.test2(""), "b", false);
check("test2(\"a\")", () => M.test2("a"), "b", false);
check("test2(\"hello world\")", () => M.test2("hello world"), "b", false);
check("test2(\"héllo, wörld\")", () => M.test2("héllo, wörld"), "b", false);
check("test2(\"abcabc\")", () => M.test2("abcabc"), "b", false);
check("test3(\"\")", () => M.test3(""), "a", false);
check("test3(\"a\")", () => M.test3("a"), "a", false);
check("test3(\"hello world\")", () => M.test3("hello world"), "a", false);
check("test3(\"héllo, wörld\")", () => M.test3("héllo, wörld"), "a", false);
check("test3(\"abcabc\")", () => M.test3("abcabc"), "a", false);
check("test4(\"\")", () => M.test4(""), "b", false);
check("test4(\"a\")", () => M.test4("a"), "b", false);
check("test4(\"hello world\")", () => M.test4("hello world"), "b", false);
check("test4(\"héllo, wörld\")", () => M.test4("héllo, wörld"), "b", false);
check("test4(\"abcabc\")", () => M.test4("abcabc"), "b", false);

console.log(`FunctionCompose01-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
